<body>
  <div class="todo-container">
    <h1>Todo List</h1>

    <div class="input-group">
      <input type="text" id="new-todo" placeholder="What needs to be done?" maxlength="100">
      <button id="add-todo">Add Todo</button>
    </div>

    <ul id="todo-list"></ul>

    <div class="filter-btns">
      <button class="filter-btn active" data-filter="all">All</button>
      <button class="filter-btn" data-filter="active">Active</button>
      <button class="filter-btn" data-filter="completed">Completed</button>
    </div>
  </div>

  <script>
    // Initialize from localStorage or empty array
    let todos = JSON.parse(localStorage.getItem('todos')) || [];

    // DOM elements
    const todoList = document.getElementById('todo-list');
    const newTodoInput = document.getElementById('new-todo');
    const addTodoBtn = document.getElementById('add-todo');
    const filterBtns = document.querySelectorAll('.filter-btn');

    // Render todos
    function renderTodos(filter = 'all') {
      todoList.innerHTML = '';

      let filteredTodos;

      if (filter === 'all') {
        filteredTodos = todos;
      } else if (filter === 'active') {
        filteredTodos = todos.filter(todo => !todo.completed);
      } else if (filter === 'completed') {
        filteredTodos = todos.filter(todo => todo.completed);
      }

      if (filteredTodos.length === 0) {
        todoList.innerHTML = '<li class="empty-state">No todos found</li>';
        return;
      }

      filteredTodos.forEach((todo, index) => {
        const li = document.createElement('li');

        if (todo.completed) {
          li.classList.add('completed');
        }

        li.innerHTML = `
          <span class="todo-text">${escapeHtml(todo.text)}</span>
          <div class="actions">
            <button class="delete-btn" data-index="${index}">Delete</button>
          </div>
        `;

        // Toggle complete on click of the text
        const todoText = li.querySelector('.todo-text');
        todoText.addEventListener('click', () => {
          toggleTodo(index);
        });

        // Delete todo
        const deleteBtn = li.querySelector('.delete-btn');
        deleteBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          deleteTodo(index);
        });

        todoList.appendChild(li);
      });
    }

    // Toggle todo completion
    function toggleTodo(index) {
      todos[index].completed = !todos[index].completed;
      saveTodos();
      renderTodos(document.querySelector('.filter-btn.active').getAttribute('data-filter'));
    }

    // Delete todo
    function deleteTodo(index) {
      todos.splice(index, 1);
      saveTodos();
      renderTodos(document.querySelector('.filter-btn.active').getAttribute('data-filter'));
    }

    // Save todos to localStorage
    function saveTodos() {
      localStorage.setItem('todos', JSON.stringify(todos));
    }

    // Escape HTML special characters
    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    // Event listeners
    addTodoBtn.addEventListener('click', () => {
      const text = newTodoInput.value.trim();
      if (text) {
        todos.push({ text, completed: false });
        newTodoInput.value = '';
        saveTodos();
        renderTodos('all');
      }
    });

    // Enter key to add todo
    newTodoInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        addTodoBtn.click();
      }
    });

    // Filter buttons
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Update active state
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const filter = btn.getAttribute('data-filter');
        renderTodos(filter);
      });
    });

    // Initial render
    renderTodos('all');
  </script>
</body>
</html>"}
